import os
import torch


class Config:
    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # File System Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the previous step
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working directory for caching processed arrays (Idea 17 specific)
    WORKING_DIR = "./working/idea_17"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Output directory for submission
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Processing / Anatomical Anchoring
    # ==========================================
    IMAGE_SIZE = 224

    # Modalities used in AA-WIIS-Net
    # Channels 0-2: FLAIR, Channels 3-5: T1wCE, Channels 6-8: T2w
    MODALITIES = ["FLAIR", "T1wCE", "T2w"]

    # Slab configuration
    NUM_SLICES_PER_SLAB = 3  # (z-1, z, z+1)
    NUM_CHANNELS = len(MODALITIES) * NUM_SLICES_PER_SLAB  # 9 channels

    # Relative depths for Anatomically-Anchored Sampling
    # We extract 3 independent slabs per subject
    SLAB_DEPTHS = [0.4, 0.5, 0.6]

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    BACKBONE = "efficientnet_b0"
    PRETRAINED = True
    DROPOUT_RATE = 0.3

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 32
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    NUM_EPOCHS = 15  # Can be overridden by training loop
    NUM_FOLDS = 5

    # ==========================================
    # Hardware
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Adjust workers based on CPU availability (12 vCPUs available)
    NUM_WORKERS = 4
